mapper.select:
SELECT tf.*, u.user_name, u.avatar, u.sex, u.age, tu.user_name as targetUserName, tu.avatar as targetUserAvatar, tu.sex as targetUserSex, tu.age as targetUserAge FROM travel_follow tf LEFT JOIN tb_user u ON tf.user_id = u.user_id LEFT JOIN tb_user tu ON tf.target_user_id = tu.user_id
and tf.user_id = #{param.userId}
and tf.target_user_id = #{param.targetUserId}
and u.user_name like concat('%', #{param.userName} ,'%')
and tu.user_name like concat('%', #{param.targetUserName}, '%')
order by tf.create_time desc
